package dev.soundceiling.app;
final class StatusText{static String capture(RuntimeState s){return switch(s.captureStatus){case RUNNING->"Захват работает";case STARTING->"Запуск захвата…";case WAITING_SIGNAL->"Ожидание звука";case STOPPED->"Захват остановлен";case ERROR->s.message;};}static String signal(RuntimeState s){return s.signalPresent?"Звук обнаружен":"Нет захватываемого звука";}static String controller(RuntimeState s){return switch(s.controlActivity){case HOLDING->"Регулятор: удерживает";case DECREASING->"Регулятор: снижает";case RAISING->"Регулятор: повышает";case MINIMUM_LIMIT->"Регулятор: ограничен слышимым минимумом";case MAXIMUM_LIMIT->"Регулятор: ограничен максимумом";case ERROR->"Регулятор: ошибка";case IDLE->"Регулятор: не активен";};}static String media(RuntimeState s){return "Media "+s.volumeIndex+"/"+s.volumeMax;}private StatusText(){}}
